"""Move particles under their mutual gravity on the GPU and summarize the result.

Usage: uv run main.py <input-file>

The input file holds "<count> <steps> <dt>" followed by one "<x> <y> <vx> <vy>"
line per particle. Every step runs two compute kernels on the GPU: one computes
each particle's acceleration from the positions the step started with, the
other applies the acceleration and then moves the particle.
"""

import math
import struct
import sys
from array import array

import wgpu

WORKGROUP_SIZE = 64
SOFTENING = 0.01

SHADER = """
struct Params {
    n: u32,
    dt: f32,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> pos: array<vec2<f32>>;
@group(0) @binding(2) var<storage, read_write> vel: array<vec2<f32>>;
@group(0) @binding(3) var<storage, read_write> acc: array<vec2<f32>>;

@compute @workgroup_size(64)
fn accelerate(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.n) {
        return;
    }
    let pi = pos[i];
    var a = vec2<f32>(0.0, 0.0);
    for (var j: u32 = 0u; j < params.n; j = j + 1u) {
        let d = pos[j] - pi;
        let r2 = dot(d, d) + 0.01;
        a = a + d / (r2 * sqrt(r2));
    }
    acc[i] = a;
}

@compute @workgroup_size(64)
fn advance(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.n) {
        return;
    }
    vel[i] = vel[i] + acc[i] * params.dt;
    pos[i] = pos[i] + vel[i] * params.dt;
}
"""


def read_input(path):
    with open(path) as f:
        tokens = f.read().split()
    count = int(tokens[0])
    steps = int(tokens[1])
    dt = float(tokens[2])
    values = [float(t) for t in tokens[3 : 3 + 4 * count]]
    xs = values[0::4]
    ys = values[1::4]
    vxs = values[2::4]
    vys = values[3::4]
    return count, steps, dt, xs, ys, vxs, vys


def open_device():
    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    return adapter.request_device_sync()


def simulate(device, count, steps, dt, xs, ys, vxs, vys):
    """Run the steps on the GPU and return the final positions and velocities."""
    pos_init = array("f", [v for i in range(count) for v in (xs[i], ys[i])])
    vel_init = array("f", [v for i in range(count) for v in (vxs[i], vys[i])])
    vec_size = 2 * 4 * count

    storage = wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC
    pos_buf = device.create_buffer_with_data(
        data=pos_init.tobytes(), usage=storage
    )
    vel_buf = device.create_buffer_with_data(
        data=vel_init.tobytes(), usage=storage
    )
    acc_buf = device.create_buffer(size=vec_size, usage=storage)
    params_buf = device.create_buffer_with_data(
        data=struct.pack("<If8x", count, dt),
        usage=wgpu.BufferUsage.UNIFORM,
    )

    if steps > 0:
        module = device.create_shader_module(code=SHADER)
        accelerate = device.create_compute_pipeline(
            layout="auto",
            compute={"module": module, "entry_point": "accelerate"},
        )
        advance = device.create_compute_pipeline(
            layout="auto",
            compute={"module": module, "entry_point": "advance"},
        )
        bind_group = device.create_bind_group(
            layout=accelerate.get_bind_group_layout(0),
            entries=[
                {"binding": 0, "resource": {"buffer": params_buf}},
                {"binding": 1, "resource": {"buffer": pos_buf}},
                {"binding": 2, "resource": {"buffer": vel_buf}},
                {"binding": 3, "resource": {"buffer": acc_buf}},
            ],
        )
        groups = (count + WORKGROUP_SIZE - 1) // WORKGROUP_SIZE

        encoder = device.create_command_encoder()
        for _ in range(steps):
            # Each pass finishes before the next one starts, so every
            # acceleration of a step sees the positions the step began with.
            compute = encoder.begin_compute_pass()
            compute.set_pipeline(accelerate)
            compute.set_bind_group(0, bind_group)
            compute.dispatch_workgroups(groups)
            compute.end()

            compute = encoder.begin_compute_pass()
            compute.set_pipeline(advance)
            compute.set_bind_group(0, bind_group)
            compute.dispatch_workgroups(groups)
            compute.end()
        device.queue.submit([encoder.finish()])

    pos = array("f")
    pos.frombytes(bytes(device.queue.read_buffer(pos_buf)))
    vel = array("f")
    vel.frombytes(bytes(device.queue.read_buffer(vel_buf)))
    return pos, vel


def summarize(count, pos, vel):
    cx = math.fsum(pos[0::2]) / count
    cy = math.fsum(pos[1::2]) / count
    px = math.fsum(vel[0::2])
    py = math.fsum(vel[1::2])
    kinetic = math.fsum(
        (vx * vx + vy * vy) / 2 for vx, vy in zip(vel[0::2], vel[1::2])
    )
    squared = math.fsum(
        (x - cx) ** 2 + (y - cy) ** 2 for x, y in zip(pos[0::2], pos[1::2])
    )
    spread = math.sqrt(squared / count)
    return cx, cy, px, py, kinetic, spread


def fmt(value):
    # Avoid printing "-0.000000" for values that are zero to the printed precision.
    if abs(value) < 5e-7:
        value = 0.0
    return f"{value:.6f}"


def main():
    count, steps, dt, xs, ys, vxs, vys = read_input(sys.argv[1])
    device = open_device()
    pos, vel = simulate(device, count, steps, dt, xs, ys, vxs, vys)
    cx, cy, px, py, kinetic, spread = summarize(count, pos, vel)
    print(f"CENTER {fmt(cx)} {fmt(cy)}")
    print(f"MOMENTUM {fmt(px)} {fmt(py)}")
    print(f"KINETIC {fmt(kinetic)}")
    print(f"SPREAD {fmt(spread)}")


if __name__ == "__main__":
    main()

